 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { OwnershipHandoverError } from "@/lib/errors";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as handoverRepo from "@/server/repositories/ownership-handover-repository";
import { notify } from "./notification-service";
import { record } from "./activity-service";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import { emit } from "@/lib/event-bus";
import { toIsoTimestamp } from "@/types/common";
import { PermissionDeniedError } from "@/lib/permissions";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { MemberId, OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary, OwnershipHandover } from "@/types/organization";

function requireRecordedOwner(actor: Actor, ownerId: UserId): void {
  if (actor.userId === ownerId) return;
  throw new PermissionDeniedError("org:delete", { allowed: false, action: "org:delete", resourceKind: "organization", reason: "denied_by_role" });
}

export async function initiateOwnershipHandover(actor: Actor, orgId: OrgId, toUserId: UserId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  requireRecordedOwner(actor, org.ownerId);
  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");
  const recipient = await memberRepo.findMember(orgId, toUserId);
  if (!recipient || recipient.status !== "active") throw new (await import("./_support")).NotFoundError("Member", toUserId);
  const existing = await handoverRepo.pending(orgId);
  if (existing) {
    if (Date.now() >= Date.parse(existing.expiresAt)) await handoverRepo.resolve(existing.id, "expired");
    else throw new OwnershipHandoverError("pending_exists");
  }
  const offer = await handoverRepo.create(orgId, actor.userId, toUserId);
  await notify(orgId, "ownership_handover", [toUserId], { title: "Workspace ownership offered", body: `${actor.userId} offered you ownership of this workspace`, href: "/settings/members", actorId: actor.userId });
  return offer;
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  const offer = await handoverRepo.pending(orgId);
  if (!offer) return null;
  if (Date.now() >= Date.parse(offer.expiresAt)) { await handoverRepo.resolve(offer.id, "expired"); return null; }
  return offer;
}

async function resolveOffer(actor: Actor, orgId: OrgId, intended: UserId | "owner", status: "declined" | "canceled"): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = await handoverRepo.pending(orgId);
  if (!offer) throw new OwnershipHandoverError("nothing_pending");
  if (Date.now() >= Date.parse(offer.expiresAt)) { await handoverRepo.resolve(offer.id, "expired"); throw new OwnershipHandoverError("expired"); }
  if (intended === "owner") {
    const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
    requireRecordedOwner(actor, org.ownerId);
    if (offer.fromUserId !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
  } else if (actor.userId !== intended || offer.toUserId !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
  return (await handoverRepo.resolve(offer.id, status))!;
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> { return resolveOffer(actor, orgId, "owner", "canceled"); }
export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> { return resolveOffer(actor, orgId, actor.userId, "declined"); }

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = await handoverRepo.pending(orgId);
  if (!offer) throw new OwnershipHandoverError("nothing_pending");
  if (Date.now() >= Date.parse(offer.expiresAt)) { await handoverRepo.resolve(offer.id, "expired"); throw new OwnershipHandoverError("expired"); }
  if (offer.toUserId !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const previous = await memberRepo.findMember(orgId, offer.fromUserId);
  const incoming = await memberRepo.findMember(orgId, offer.toUserId);
  if (!previous || previous.status !== "active" || !incoming || incoming.status !== "active") { await handoverRepo.resolve(offer.id, "canceled"); throw new OwnershipHandoverError("nothing_pending"); }
  const resolved = await handoverRepo.resolve(offer.id, "accepted");
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");
  await orgRepo.setOwner(orgId, actor.userId);
  if (incoming.role !== "owner") {
    const changed = await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", { ...actorEnvelope(actor), memberId: changed.id, from: incoming.role, to: "owner" });
  }
  if (previous.role === "owner") {
    const changed = await memberRepo.updateMemberRole(orgId, previous.id, "admin");
    await emit("member.role_changed", { ...actorEnvelope(actor), memberId: changed.id, from: "owner", to: "admin" });
  }
  await emit("organization.ownership_transferred", { ...actorEnvelope(actor), fromUserId: offer.fromUserId, toUserId: actor.userId });
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}
